/// The leaf cell of a point.
pub fn leaf(lat: f64, lng: f64) -> TestResult<CellId> {
    CellId::at(lat, lng).context("a finite point")
}

/// The cells of a point known to within `metres`, sorted.
pub fn radius_cells(lat: f64, lng: f64, metres: f64) -> TestResult<Vec<CellId>> {
    let mut found = cells_around(lat, lng, metres).context("finite inputs")?;
    found.sort();
    Ok(found)
}

/// A face's level-0 cell: the face in the top three bits, the level marker below.
pub fn face_cell(face: u64) -> CellId {
    CellId::new((face << 61) | (1 << 60))
}
